def EAN13(n):
    cc = int(n[len(n) - 1])
    p = Traitement(n)
    if (cc == p):
        print("Le code est valide")
    else:
        print("Le code n'est valide")


def Traitement(n):
    ch = n[:len(n) - 1]
    S = 0
    for i in range(len(ch)):
        if (i + 1) % 2 == 0:
            S = S + (int(ch[i])) * 3
        else:
            S = S + int(ch[i])
    r = S % 10
    p = 10 - r
    return p


